VALUES (
  '20000000-0000-0000-0000-000000000999'::uuid,
  '00000000-0000-0000-0000-000000000994'::uuid,
  'P005_RECIPIENT','P005 Recipient',
  '10000000-0000-0000-0000-000000000994'::uuid,'ACTIVE'
