ON CONFLICT DO NOTHING;

UPDATE org.employee
   SET primary_position_id='20000000-0000-0000-0000-000000000999'::uuid,updated_at=now()
 WHERE tenant_id='00000000-0000-0000-0000-000000000994'::uuid
   AND id IN (
     '30000000-0000-0000-0000-000000000994'::uuid,
     '30000000-0000-0000-0000-000000000996'::uuid
   );

UPDATE org.employee_position
   SET position_id='20000000-0000-0000-0000-000000000999'::uuid,updated_at=now()
 WHERE tenant_id='00000000-0000-0000-0000-000000000994'::uuid
   AND employee_id IN (
     '30000000-0000-0000-0000-000000000994'::uuid,
     '30000000-0000-0000-0000-000000000996'::uuid
   )
   AND is_primary AND NOT is_deleted;

UPDATE iam.user_identity
   SET position_id='20000000-0000-0000-0000-000000000999'::uuid,updated_at=now()
 WHERE tenant_id='00000000-0000-0000-0000-000000000994'::uuid
   AND id IN (
     '60000000-0000-0000-0000-000000000994'::uuid,
     '60000000-0000-0000-0000-000000000996'::uuid
   );

